
-- v6.4 consumer data migration. Apply after 45 baseline in one transaction.
BEGIN;
CREATE TABLE requirement_intakes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, project_id uuid NOT NULL, version integer NOT NULL CHECK(version>0), original_text text NOT NULL, locale text NOT NULL CHECK(locale IN ('fa','en')), assumptions jsonb NOT NULL DEFAULT '[]', acceptance_criteria jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), UNIQUE(tenant_id,project_id,version), FOREIGN KEY(tenant_id,project_id) REFERENCES projects(tenant_id,id));
CREATE TABLE revisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, project_id uuid NOT NULL, parent_revision_id uuid, commit_sha char(40) NOT NULL CHECK(commit_sha ~ '^[0-9a-f]{40}$'), evidence_digest char(64) NOT NULL CHECK(evidence_digest ~ '^[0-9a-f]{64}$'), summary text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), UNIQUE(tenant_id,project_id,id), UNIQUE(tenant_id,project_id,commit_sha,evidence_digest), FOREIGN KEY(tenant_id,project_id) REFERENCES projects(tenant_id,id), FOREIGN KEY(tenant_id,project_id,parent_revision_id) REFERENCES revisions(tenant_id,project_id,id));
CREATE TABLE previews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, project_id uuid NOT NULL, revision_id uuid NOT NULL, state text NOT NULL DEFAULT 'requested' CHECK(state IN ('requested','building','verifying','ready','failed','expired','revoked')), health text NOT NULL DEFAULT 'unknown' CHECK(health IN ('unknown','healthy','unhealthy')), expires_at timestamptz NOT NULL, access_policy text NOT NULL CHECK(access_policy IN ('project_members','explicit_grants')), url text, evidence_digest char(64), version bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), UNIQUE(tenant_id,project_id,id), FOREIGN KEY(tenant_id,project_id,revision_id) REFERENCES revisions(tenant_id,project_id,id), CHECK(state <> 'ready' OR (health='healthy' AND url IS NOT NULL AND evidence_digest IS NOT NULL)));
CREATE TABLE visual_feedback(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, project_id uuid NOT NULL, preview_id uuid NOT NULL, revision_id uuid NOT NULL, author_id uuid NOT NULL REFERENCES actors(id), comment text NOT NULL CHECK(length(comment)>0), target jsonb NOT NULL, screenshot_artifact_id uuid, redaction_verified boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','triaged','implemented','rejected')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,project_id,preview_id) REFERENCES previews(tenant_id,project_id,id), FOREIGN KEY(tenant_id,project_id,revision_id) REFERENCES revisions(tenant_id,project_id,id), FOREIGN KEY(tenant_id,screenshot_artifact_id) REFERENCES artifacts(tenant_id,id), CHECK(screenshot_artifact_id IS NULL OR redaction_verified));
CREATE TABLE acceptance_decisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, project_id uuid NOT NULL, revision_id uuid NOT NULL, reviewer_id uuid NOT NULL REFERENCES actors(id), evidence_digest char(64) NOT NULL, decision text NOT NULL CHECK(decision IN ('accepted','rejected')), criterion_ids uuid[] NOT NULL CHECK(cardinality(criterion_ids)>0), version bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), UNIQUE(tenant_id,project_id,id), FOREIGN KEY(tenant_id,project_id,revision_id) REFERENCES revisions(tenant_id,project_id,id));
CREATE TABLE delivery_receipts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, project_id uuid NOT NULL, revision_id uuid NOT NULL, acceptance_decision_id uuid NOT NULL, evidence_digest char(64) NOT NULL, artifact_hashes jsonb NOT NULL, instructions text NOT NULL, caveats jsonb NOT NULL DEFAULT '[]', status text NOT NULL CHECK(status IN ('prepared','delivered','revoked')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,project_id,revision_id) REFERENCES revisions(tenant_id,project_id,id), FOREIGN KEY(tenant_id,project_id,acceptance_decision_id) REFERENCES acceptance_decisions(tenant_id,project_id,id));
CREATE TABLE consumer_cost_forecasts(tenant_id uuid NOT NULL, project_id uuid NOT NULL, spent numeric(18,6) NOT NULL CHECK(spent>=0), reserved numeric(18,6) NOT NULL CHECK(reserved>=0), authorized_cap numeric(18,6) NOT NULL CHECK(authorized_cap>=0), estimate_low numeric(18,6) NOT NULL CHECK(estimate_low>=0), estimate_high numeric(18,6) NOT NULL CHECK(estimate_high>=estimate_low), assumptions jsonb NOT NULL DEFAULT '[]', updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,project_id), FOREIGN KEY(tenant_id,project_id) REFERENCES projects(tenant_id,id), CHECK(spent+reserved<=authorized_cap));
CREATE INDEX previews_by_project ON previews(tenant_id,project_id,created_at DESC);
CREATE INDEX feedback_by_revision ON visual_feedback(tenant_id,project_id,revision_id);
CREATE INDEX acceptance_by_revision ON acceptance_decisions(tenant_id,project_id,revision_id);
-- Fail closed unless session tenant is set by trusted backend after authentication.
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['requirement_intakes','revisions','previews','visual_feedback','acceptance_decisions','delivery_receipts','consumer_cost_forecasts'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY tenant_scope ON %I USING (tenant_id = NULLIF(current_setting(''app.tenant_id'',true),)::uuid) WITH CHECK (tenant_id = NULLIF(current_setting(app.tenant_id,true),)::uuid)',t); END LOOP; END $$;
COMMIT;
